insert into public.sim_measures(id,version_id,category_id,name,description,competencies,initial_cost,quarterly_cost,duration_turns,delay_turns,model_parameters) values('a2_freeze','alpha-2','a2_controls','Congelación temporal de alquileres','Congelar rentas vigentes protege contratos cubiertos; puede reducir nuevas ofertas',array['national','regional'],800000,300000,8,0,'{"id": "a2_freeze", "category": "controls", "name": "Congelación temporal de alquileres", "full_application": "100 % del parque elegible", "initial_cost": 800000, "quarterly_cost": 300000, "duration_turns": 8, "delay_turns": 0, "happiness": [-9.0, -8.0, 9.0, 2.0, 1.0, 0.0], "price": {"rent": -5.0, "sale": -2.0, "free_rent": 4.0}, "mechanism": "Congelar rentas vigentes protege contratos cubiertos; puede reducir nuevas ofertas", "pros": ["Estabilidad inmediata de quienes tienen contrato"], "cons": ["Retirada de oferta y selección de inquilinos"], "sources": ["sf_rent", "berlin", "lau"], "curve": "saturating", "permanent": false, "exclusive_group": "rent_control", "risk_high": true, "legal_status": "design_subject_to_legal_review", "coefficient_status": "game_assumption_not_empirical_estimate", "unit_cost_status": "estimate", "competencies": ["national", "regional"], "rationales": ["Renta y derechos de gestión de las viviendas cubiertas. Perjuicio potencial antes de financiación.", "Retorno esperado y capacidad de cambiar de uso. Perjuicio potencial antes de financiación.", "Protección de beneficiarios frente a dificultad de los nuevos demandantes. Beneficio potencial antes de financiación.", "Oferta de compra y cambios desde alquiler hacia venta. Beneficio potencial antes de financiación.", "Acceso a compra y exposición a retorno o restricciones. Beneficio potencial antes de financiación.", "Efectos indirectos sobre vecindario y valor patrimonial. Efecto directo limitado antes de financiación."]}'::jsonb);
