insert into public.sim_scenarios(version_id,city_id,code,name,baseline_date,is_synthetic,rent_m2,sale_m2,reference_area_m2,assumptions)
insert into public.sim_scenario_groups select newer.id,g.group_id,g.weight_percent,g.initial_unrest from public.sim_scenarios newer join public.sim_scenarios old on old.city_id=newer.city_id and old.code=newer.code and old.version_id='alpha-1' join public.sim_scenario_groups g on g.scenario_id=old.id where newer.version_id='alpha-2';
insert into public.sim_scenario_budgets select s.id,b.id,round((b.reference_parameters->>'annual_reference')::numeric*(b.reference_parameters->>'sandbox_share')::numeric*(b.reference_parameters->>'max_adjustment')::numeric*(b.reference_parameters->>'response')::numeric/4,2) from public.sim_scenarios s cross join public.sim_budget_sources b where s.version_id='alpha-2' and b.id like 'a2_%';
 insert into public.sim_turns(run_id,turn_no,simulated_date,rent_m2,sale_m2,collective_unrest,reference_area_m2,summary,state)
 insert into public.sim_turn_groups(run_id,turn_no,group_id,unrest,weight_percent,explanation)
  insert into public.sim_decisions(run_id,turn_no,slot,measure_id,intensity,initial_cost,quarterly_cost,end_turn,effect_start_turn,measure_snapshot,post_quarterly_cost)
   insert into public.sim_funding(decision_id,run_id,source_id,initial_amount,quarterly_amount,post_quarterly_amount)
 insert into public.sim_turn_budgets(run_id,turn_no,source_id,capacity,committed)
