alter table public.sim_measures add column model_parameters jsonb not null default '{}'::jsonb;
alter table public.sim_budget_sources add column reference_parameters jsonb not null default '{}'::jsonb;
alter table public.sim_decisions add column post_quarterly_cost numeric(14,2) not null default 0 check(post_quarterly_cost>=0);
alter table public.sim_funding add column post_quarterly_amount numeric(14,2) not null default 0 check(post_quarterly_amount>=0);
create table public.sim_sources(id text primary key,title text not null,url text not null,kind text not null,accessed_on date not null);
create table public.sim_measure_sources(measure_id text not null references public.sim_measures(id),source_id text not null references public.sim_sources(id),primary key(measure_id,source_id));
create index sim_measure_sources_source_idx on public.sim_measure_sources(source_id);
alter table public.sim_sources enable row level security;
alter table public.sim_measure_sources enable row level security;
revoke all on public.sim_sources,public.sim_measure_sources from anon,authenticated;
grant select on public.sim_sources,public.sim_measure_sources to anon,authenticated;
create policy catalogue_read on public.sim_sources for select to anon,authenticated using(true);
create policy catalogue_read on public.sim_measure_sources for select to anon,authenticated using(true);

select 'alpha-2',city_id,code,name,baseline_date,true,rent_m2,sale_m2,reference_area_m2,assumptions||'{"model":"alpha-2","budget":"Historical national 2023 reference with hypothetical 1% sandbox allocation","coefficients":"game hypotheses, uncalibrated"}'::jsonb from public.sim_scenarios where version_id='alpha-1';

create function simulator_private.calculate_alpha2(p_run_id uuid,p_turn integer)
returns void language plpgsql security invoker set search_path='' as $$
declare r public.sim_runs; b public.sim_turns; d record; s record; g record; params jsonb;
 h numeric[]:=array[0,0,0,0,0,0]::numeric[]; rents numeric:=0; sales numeric:=0; frees numeric:=0;
 force numeric; maturity numeric; risk numeric; ratio numeric; i integer;
 has_admin boolean:=false;has_build boolean:=false;has_aid boolean:=false;has_control boolean:=false;
begin
 select * into r from public.sim_runs where id=p_run_id and user_id=auth.uid();
 if not found then raise exception 'Run not owned' using errcode='42501'; end if;
 select * into b from public.sim_turns where run_id=r.id and turn_no=0;
 for d in select * from public.sim_decisions where run_id=r.id loop
  params:=d.measure_snapshot->'model_parameters';
  if p_turn<d.effect_start_turn then continue; end if;
  if p_turn>d.end_turn and not coalesce((params->>'permanent')::boolean,false) then continue; end if;
  maturity:=greatest(0,least(1,(p_turn-d.effect_start_turn+1)::numeric/4));
  force:=(1-exp(-2*d.intensity))/(1-exp(-2::numeric))*maturity;
  rents:=rents+coalesce((params->'price'->>'rent')::numeric,0)*force;
  sales:=sales+coalesce((params->'price'->>'sale')::numeric,0)*force;
  frees:=frees+coalesce((params->'price'->>'free_rent')::numeric,0)*force;
  for i in 1..6 loop h[i]:=h[i]+coalesce((params->'happiness'->>(i-1))::numeric,0)*force;end loop;
  if coalesce((params->>'risk_high')::boolean,false) and d.intensity>0.75 then
   risk:=power((d.intensity-0.75)/0.25,2)*maturity;h[3]:=h[3]-2*risk;h[2]:=h[2]-risk;frees:=frees+risk;
  end if;
  has_admin:=has_admin or params->>'category'='admin';has_build:=has_build or params->>'category'='supply';
  has_aid:=has_aid or d.measure_id like '%rent_aid%';has_control:=has_control or coalesce(params->>'exclusive_group'='rent_control',false);
 end loop;
 if has_admin and has_build then rents:=rents-0.5;sales:=sales-0.5;end if;
 if has_aid and has_control then frees:=frees+0.5;h[3]:=h[3]-1;end if;
 for s in select tb.*,bs.reference_parameters from public.sim_turn_budgets tb join public.sim_budget_sources bs on bs.id=tb.source_id where tb.run_id=r.id and tb.turn_no=p_turn loop
  ratio:=case when s.capacity>0 then greatest(0,least(1,s.committed/s.capacity)) else 0 end;
  for i in 1..6 loop h[i]:=h[i]+coalesce((s.reference_parameters->'happiness'->>(i-1))::numeric,0)*ratio;end loop;
 end loop;
 for g in select tg.*,gr.display_order from public.sim_turn_groups tg join public.sim_groups gr on gr.id=tg.group_id where tg.run_id=r.id and tg.turn_no=0 loop
  update public.sim_turn_groups set unrest=round(greatest(0,least(100,g.unrest-20*tanh(h[g.display_order]::double precision/20)))::numeric,2),
  explanation='Hipótesis alfa: efectos modulados, maduración e incidencia de financiación. No medición de opinión pública.' where run_id=r.id and turn_no=p_turn and group_id=g.group_id;
 end loop;
 update public.sim_turns set rent_m2=round(b.rent_m2*(1+p_turn*0.001)*(1+25*tanh(rents::double precision/25)/100)::numeric,2),
 sale_m2=round(b.sale_m2*(1+p_turn*0.0015)*(1+25*tanh(sales::double precision/25)/100)::numeric,2),
 collective_unrest=(select round(sum(unrest*weight_percent)/100,2) from public.sim_turn_groups where run_id=r.id and turn_no=p_turn),
 summary='Hipótesis alfa sin calibración: precios, malestar y financiación calculados con catálogo investigado y coeficientes de juego.',
 state=jsonb_build_object('synthetic',true,'model_version','alpha-2','coefficient_status','game_assumption_not_empirical_estimate','free_rent_m2',round((b.rent_m2*(1+p_turn*0.001)*(1+25*tanh(frees::double precision/25)/100))::numeric,2))
 where run_id=r.id and turn_no=p_turn;
end $$;
revoke all on function simulator_private.calculate_alpha2(uuid,integer) from public,anon,authenticated;

create or replace function simulator_private.advance_turn(p_run_id uuid,p_expected_turn integer,p_decisions jsonb)
returns integer language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); r public.sim_runs; s public.sim_scenarios; m public.sim_measures;
 next_t integer; j jsonb; f jsonb; slot integer:=0; did uuid; intensity numeric; si numeric; sq numeric; needed_i numeric; needed_q numeric; needed_post numeric;
begin
 if u is null then raise exception 'Authentication required' using errcode='42501'; end if;
 select * into r from public.sim_runs where id=p_run_id and user_id=u for update;
 if not found then raise exception 'Run not found or not owned' using errcode='42501'; end if;
 if p_expected_turn is null or r.current_turn<>p_expected_turn then raise exception 'Stale turn: refresh saved game' using errcode='40001'; end if;
 if r.status<>'active' then raise exception 'Game already completed'; end if;
 if p_decisions is null or jsonb_typeof(p_decisions)<>'array' then raise exception 'Decisions must be an array'; end if;
 if jsonb_array_length(p_decisions)>5 or octet_length(p_decisions::text)>32768 then raise exception 'Maximum five decisions'; end if;
 select * into s from public.sim_scenarios where id=r.scenario_id;
 next_t:=r.current_turn+1;
 -- Deliberately illustrative trajectory. Policies are recorded and financed, but their economic effects are not calibrated.
 values(r.id,next_t,(s.baseline_date+make_interval(months=>next_t*3))::date,
 round(s.rent_m2*(1+next_t*0.001),2),round(s.sale_m2*(1+next_t*0.0015),2),0,s.reference_area_m2,
 'Trayectoria ficticia. Las medidas se registran y financian; sus efectos económicos aún no se calculan.',
 jsonb_build_object('synthetic',true,'model_version',r.version_id));
 select r.id,next_t,group_id,greatest(0,least(100,initial_unrest+round(sin(next_t*0.6)*2))),weight_percent,'Oscilación ilustrativa; no es efecto de las medidas'
 from public.sim_scenario_groups where scenario_id=s.id;
 update public.sim_turns set collective_unrest=(select round(sum(unrest*weight_percent)/100,2) from public.sim_turn_groups where run_id=r.id and turn_no=next_t)
 where run_id=r.id and turn_no=next_t;
 for j in select value from jsonb_array_elements(p_decisions) loop
  slot:=slot+1;
  select * into m from public.sim_measures where id=j->>'measure_id' and version_id=r.version_id;
  if not found then raise exception 'Unknown measure for this model version'; end if;
  intensity:=coalesce((j->>'intensity')::numeric,1);
  if intensity<=0 or intensity>m.max_intensity then raise exception 'Invalid intensity'; end if;
  if exists(select 1 from public.sim_decisions where run_id=r.id and measure_id=m.id and end_turn>=next_t) then raise exception 'Measure already active'; end if;
  if m.model_parameters->>'exclusive_group' is not null and exists(select 1 from public.sim_decisions d where d.run_id=r.id and d.end_turn>=next_t and d.measure_snapshot->'model_parameters'->>'exclusive_group'=m.model_parameters->>'exclusive_group') then raise exception 'Conflicting measure in exclusive policy family'; end if;
  needed_i:=round(m.initial_cost*intensity,2);needed_q:=round(m.quarterly_cost*intensity,2);
  needed_post:=round(coalesce((m.model_parameters->'cost_breakdown'->>'annual_maintenance_per_home')::numeric,0)*coalesce((m.model_parameters->'cost_breakdown'->>'homes_at_full')::numeric,0)*intensity/4,2);
  values(r.id,next_t,slot,m.id,intensity,needed_i,needed_q,next_t+m.duration_turns-1,next_t+m.delay_turns,to_jsonb(m),needed_post) returning id into did;
  if j->'funding' is not null and jsonb_typeof(j->'funding')<>'array' then raise exception 'Funding must be an array'; end if;
  for f in select value from jsonb_array_elements(coalesce(j->'funding','[]'::jsonb)) loop
   if not exists(select 1 from public.sim_scenario_budgets where scenario_id=s.id and source_id=f->>'source_id') then raise exception 'Funding source unavailable'; end if;
   values(did,r.id,f->>'source_id',coalesce((f->>'initial_amount')::numeric,0),coalesce((f->>'quarterly_amount')::numeric,0),case when needed_q>0 then round(needed_post*coalesce((f->>'quarterly_amount')::numeric,0)/needed_q,2) else 0 end);
  end loop;
  select coalesce(sum(initial_amount),0),coalesce(sum(quarterly_amount),0) into si,sq from public.sim_funding where decision_id=did;
  if si<>needed_i or sq<>needed_q then raise exception 'Funding must exactly cover initial and quarterly costs'; end if;
 end loop;
 -- Reject duplicate use of funds now AND in future quarters. Prior recurring commitments remain reserved.
 if exists(
  select 1 from generate_series(next_t,r.max_turns) as quarters(t)
  cross join public.sim_scenario_budgets b
  where b.scenario_id=s.id and b.quarterly_capacity < (
   select coalesce(sum(case when quarters.t>d.end_turn then f.post_quarterly_amount else f.quarterly_amount+case when d.turn_no=quarters.t then f.initial_amount else 0 end end),0)
   from public.sim_funding f join public.sim_decisions d on d.id=f.decision_id
   where d.run_id=r.id and f.source_id=b.source_id and d.turn_no<=quarters.t and (d.end_turn>=quarters.t or f.post_quarterly_amount>0))
 ) then raise exception 'Funding source capacity exceeded in this or a future quarter'; end if;
 select r.id,next_t,b.source_id,b.quarterly_capacity,
 coalesce((select sum(case when next_t>d.end_turn then f.post_quarterly_amount else f.quarterly_amount+case when d.turn_no=next_t then f.initial_amount else 0 end end)
 from public.sim_funding f join public.sim_decisions d on d.id=f.decision_id where d.run_id=r.id and f.source_id=b.source_id and d.turn_no<=next_t and (d.end_turn>=next_t or f.post_quarterly_amount>0)),0)
 from public.sim_scenario_budgets b where b.scenario_id=s.id;
 if r.version_id='alpha-2' then perform simulator_private.calculate_alpha2(r.id,next_t); end if;
 update public.sim_runs set current_turn=next_t,status=case when next_t=max_turns then 'completed' else 'active' end,updated_at=now() where id=r.id;
 return next_t;
end $$;
